import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"西溪易說卷十","description":"西溪易說 - 西溪易說卷十","frontmatter":{"title":"西溪易說卷十","description":"西溪易說 - 西溪易說卷十"},"headers":[],"relativePath":"classics/xixi/011.md","filePath":"classics/xixi/011.md"}'),i={name:"classics/xixi/011.md"};function r(c,p,_,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="西溪易說卷十" tabindex="-1">西溪易說卷十 <a class="header-anchor" href="#西溪易說卷十" aria-label="Permalink to “西溪易說卷十”">​</a></h1><p>欽定四庫全書</p><p>宋李過撰</p><p>䷭ 巽下坤上</p><p>升。</p><p>升：元亨。用見大人，勿恤，南征吉。象曰：柔以時升，巽而順，剛中而應，是以大亨。「用見大人，勿恤」，有慶也。「南征吉」，志行也。坤上巽下，木生地中，自下升上之義。古之賢者升進於上，其道不一。有自司徒命卿論秀而升者；自司徒升之司樂，樂正升之司馬，司馬升之王所；有自侯方歲貢而升者，天子則試之射宮，中多者得與於祭。有自三年大比，因賢能之書而升者，天子拜受，登於天府。古者進升之道，大略如此。其條目纖悉，見於周官之職掌，與王制所載，而其義則隱於易之「升」。蓋木之升也，其勾末萌甲未拆之時，枝柯幹葉皆備於未升之時。及其得地，故其升也莫能御。猶賢者方其未進也，道德蓄蓄，皆當素備，故一齣而名實遂孚矣。卦辭：升：元亨。君子之升，大亨之道也。用見大人，勿恤。大人，九五也。升而至五，則見君矣，宜無愛也。自巽至坤，皆離位也，故「南征吉」。象曰：「柔以時升。」謂初六柔自下而升，九二剛得中，六五在上，為己之應，是以「大亨」也。得見大人，則「有慶」矣，故無憂也。卦屬南方，「離」明，萬物相見，木道至此，其志乃行，故曰：「南征吉，志行也。」象曰：地中生木，「升」；君子以順德，積小以高大。</p><p>「地中生木」，以漸而升。君子之升，不能遽進也，體二象之順，積小以高大。蓋「坤」以順為德，「巽」亦以順為德也。古人進身自有次第，不容躐等。</p><p>初六：允升，大吉。象曰：「允升大吉」，上合志也。</p><p>允，信也。初在下，猶其未升也，須誠實充足，然後進而大吉。故賢者之未升，必其行懋於家，德信於鄉，然後可以論進。此自卿大夫而升，命鄉論秀而升，皆自下推澤而進也。象曰「上合志也」，謂上合六五之志也。</p><p>九二：孚乃利用礿，無咎。象曰：九二之孚，有喜也。</p><p>進而至二，五為正應，潛德之孚於君矣，故宜用礿，不必其禮文之備也。此不由三道而升，自以德孚於君，是以為不次之升。如傅說之於高宗，以夢而升是也；太公之於文王，以卜而升是也。象曰「有喜也」，君臣相孚，故「有喜」也。</p><p>九三：升虛邑。象曰：「升虛邑」，無所疑也。又進至三，三，諸侯之位；邑，國也。進而至此，則一國皆推其善士矣，又何疑焉！此自侯國而升也，故曰「升虛邑」。象曰「無所疑也」，謂德孚於邑國，可以無疑也。</p><p>六四，王用享於岐山，吉，無咎。象曰：「王用享於岐山」，順事也。</p><p>四，卿位，至此所謂升之司馬，將論以進於王也。王，即六五也；岐山，西山也。此互體兌之上，故曰「岐山」。言六五之王，將論定而官之，是「享於岐山」也，象曰「順事也」。進而至此，既得卦體，故曰「順事」。</p><p>六五，貞吉，升階。象曰：「貞吉升階」，大得志也。</p><p>至此則進於天子之階矣。或升之王，或試之射宮，或登之天府，皆所謂「升階」也，則升道亨矣，故曰「貞吉」，象曰「大得志也」。升而至階，得志可知也。</p><p>上六，置升，利於不息之貞。象曰：「置升」在上，消不富也。處升之極，知進而不知退，則顛置乎利達者也。君子知進退存亡，故宜貞守，貞守乃所以不息也。猶如木升之極，必歸根覆命，雖華實剝落，而生生之意又寓於其中矣，所謂「利不息之貞」也。象曰：冥升在上，消不富也。升極則反，其道消矣。以柔居之，故曰「不富」。䷮ 坎下兗上</p><p>困</p><p>困：亨。貞大人吉，無咎，有言不信。彖曰：「困」，剛揜也。險以說，困而不失其所亨，其惟君子乎？「貞，大人吉」，以剛中也。「有言不信」，尚口乃窮也。</p><p>困，剛揜也。三陽處三陰之間，陽為陰所揜，是君子為小人所困也。然困而亨，蓋惟君子為能處困，身處困而道未嘗不亨也。「貞大人吉」，謂九五也。九五謂困之主，舉小人而去之，則君子之道亨而得「貞吉」矣。「有言不信」，君子處困，正當自守，難以口舌辨也。彖：困，剛揜也。剛為陰所揜也。卦坎險而兌說，險難而以說處之，困而不失其所亨，用此道也。此惟君子能之，被兵於匡、宋，絕糧於陳、蔡，而道未嘗少貶，皆聖人事也。九五以剛居中，能困亨者也，故曰「以剛中也」。處困之時，遜言以避禍，故尚口乃窮也。六爻之義，聖人卻有深意。據君子為小人所困，陽爻為君子，陰爻為小人，則陽爻當困，而陰爻當吉。然聖人設義，初為陰爻，「困於株木」；三為陰爻，「困於疾藜」；上為陰爻，「困於葛藟」。三陰爻皆兇。九二雖困，乃「朱紱方來」；九四雖淵，其終反吉。九五雖困，「乃徐有說」；三陽爻反吉，以見小人之困君子，君子終不可困，而小人實自困也。自古小人之困君子，未有不自敗者。聖人設此義以防民，而後世小人猶有無忌憚者。</p><p>象曰：澤無水，困。君子以致命遂志。</p><p>君子處困之道固如此。</p><p>初六：臀困於株木，入於幽谷，三歲不覿。象曰：「入於幽谷」，幽不明也。</p><p>初與四為正應，四，君子也。今有困君子之意，故為九四所絕。四處互體「巽」，「巽」為木，初欲託庇於其下，已不能矣，故「困於株木」。自處「坎」之下，「坎」，北方，幽都也，故曰「入於幽谷」。越三爻而求九四，不能覿，言為君子所棄也。象曰「幽不明也」。</p><p>九二，困於酒食，朱紱方來，利用享祀。徵兇，無咎。象曰：「困於酒食」，中有慶也。</p><p>二處「坎」中，「坎」為酒食，上下為同體二陰所困，所困特飲食，言所困之者小也。「朱紱」，君之服，謂九五也。詩曰：「朱紱斯皇，室家君王。」言九五將以同德來相求也，故曰「方來」。君臣同德，則可以受福，故「利用享祀」。然處二陰之中，未可往也，故「徵㓙」；其困終亨，故「無咎」。象曰「中有慶也」。見得君子未嘗困。</p><p>六三：困於石，據於蒺藜，入於其宮，不見其妻㓙。象曰：「據於蒺藜」，乘剛也；「入於其宮，不見其妻」，不祥也。</p><p>三陰爻本欲困君子，今乃麗於二陽之間，反為君子所困。前遇九四「困於石」也，退遇九二，「據於蒺藜」也。上六已應也，已「困於葛藟」，是「不見其妻」也。象曰「乘剛也」，謂乘九二之剛也。「不見其妻」，不祥也。繫辭子曰：「非所困而困焉，名必辱；非所據而據焉，身必危。」既辱且危，死期將至，妻其可得見乎？</p><p>九四，來徐徐，困於金車，吝，有終。象曰：「來徐徐」，志在下也。雖不當位，有與也。</p><p>三陽以同德相光，幾二在下，陷乎二陰之間，未能即來也，故「來徐徐」。上體兌為金，下體坎為輪，是金車也。金車可以行，處困之時，未得行也。雖「吝」，然終必相求，故「有終」。象曰：「來徐徐」，志在下也；謂九二也。雖不當位，有與也。四爻所處之位雖不當，然君子以同德相求，故「有與」。前輩謂小人無黨，蓋小人以利合，終必相傾；君子以理合，終必相與。</p><p>九五，劓刖，困於赤紱，乃徐有說，利用祭祀。象曰：「劓刖」，志未得也；「乃徐有說」，以中直也。「利用祭祀」，受福也。</p><p>五以陽剛處君位，乃使小人得以困君子，是誰之咎也？五威福之權在己，不過去上下之小人，則君子亨矣。「劓刖」也者，用劓刑以劓在上之小人，謂上六也；用刖刑以刖在下之小人，謂三與初也。「赤紱」，臣服。詩曰：「彼其之子，三百赤紱。」謂九二也。上下小人既去，則曏者所困之赤紱乃徐徐而來，以同德而相說也。君臣同德，則必受福，故「利用祭祀」。象以君子未得志而施刑，故曰「志未得」也。九二居中而相應，故曰「以中直也」；祭必受福，故曰「受福也」。</p><p>上六：困於葛藟，於臲卼，曰動悔有悔，徵吉。象曰：「困於葛藟」，未當也；「動悔有悔」，吉行也。小人扳援而據上位，猶葛藟也。然小人不宜在上，故「臲卼」不安。九五之君有施刑之志，聖人故戒之曰「動必悔」，不容幸免也。必有悔而往則吉，謂小人無故困君子，不獲罪而去，則終必有聊辱之禍，故曰「動悔有悔，吉行也」。謂小人能有悔而去，是小人之福也，是以「吉行也」。䷯ 巽下坎上</p><p>井</p><p>井：改邑不改井，無喪無得，往來井井。汔至，亦未繘井，羸其瓶，兇。彖曰：巽乎水而上水，井。井養而不窮也。「改邑不改井」，乃以剛中也。「汔至亦未繘井」，未有功也。「羸其瓶」，是以兇也。</p><p>巽下坎上木上有水為井。木，井榦也，轆轤之幹也。汲井者，必登於木幹之上，上水下木，汲之象也。邑人所居，其中有井。都邑有遷徙，而井常不移。故曰「改邑不改井，無喪無得，往來井井」。湘卿雲：利物而不費，無喪也；功成而不居，無得也。來而汲，則不拒；汲而去，則不追。人有往來，而井之為井，常自若也。汲至則亦未繘井。汔，水涸也。繘，綆。當水涸而至，則未施綆而汲，汲則羸其瓶。蓋井水既涸，則無以受瓶也，故「兇」。彖：「巽乎水而上水，井。」此汲井之義也。汲者以器巽乎水，然後汲而上。井道以出為功，故曰「上水，井」。井養而不窮，此言井之德，養物之功，更無窮極，惟有井之德，所以酌而不匱也。邑可改而井不可改者，以二五剛得中，惟中有定守，所以不隨世變移也。當水涸而至，未能有功，是以有「羸其瓶」之「兇」也。見在二爻。</p><p>象曰：木上有水，「井」；君子以勞民勸相。</p><p>「勞民勸相」，則恩意浹洽，猶井之澤也。七月之詩，九功之歌，沐浴膏澤而歌詠勞苦，皆古人「勸相」之事也。</p><p>初六，井泥不食，舊井無禽。象曰：「井泥不食」，下也。「舊井無禽」，時舍也。</p><p>井卦六爻，剛領最好。初「井泥」，二「井谷」，皆廢井也。三「井渫」，則渫初之泥；四「井甃」，則甃二之谷。泥既渫，谷既甃，則井道全矣。故五爻「井冽」而泉寒，上爻則收而「勿幕」，功用始及物，而井道大成矣。初六處最下，故為「井泥」。井水貴清而泥濁之，宜其不食，故井廢而「舊禽」亦不往焉。謂失井之道，為時所棄也，故象曰「時舍也」。</p><p>九二，井谷射鮒，甕敝漏。象曰：「井谷射鮒」，無與也。</p><p>二居初之上，而體則巽下，是井湮而為谷也。井既為谷，其水必涸，但鮒蟆相射而已。於此施綆，甕必敝漏，蓋無以受甕也，即彖所謂「羸其瓶」是也。象曰「無與也」，謂二所以為谷者，以「無與」也。四為之甃，則有與矣。</p><p>九三，井渫不食，為我心惻，可用汲。王明，並受其福。象曰：「井渫不食」，行惻也；求「王明」，受福也。</p><p>三言「井渫」，渫初之泥也，所謂「浚井」也。井泥雖浚，人猶未食，故至者心惻然，以井澤未能及物也，雖然，亦可用汲矣。猶之人也，已德既治，有明王在上，汲而進之，則天下蒙福矣。象曰：「行惻也」，言行者見之惻然也。求「王明」，受福也。六四，井甃，無咎。象曰：「井甃無咎」，修井也。</p><p>四「井甃」，甃二之谷也，所謂修井也。谷既甃，則井之體全矣，象曰：「修井也。」初與二爻在下體，為井之地，故初「井泥」，二「井谷」。三與四居人位，必盡人事，故三「井渫」而四「井甃」，以人事言也。五與上則得之天矣，是以三才之位取義也。</p><p>九五，井洌，寒泉食。象曰：「寒泉」之食，中正也。</p><p>井至五爻，初泥已浚，二谷已修，井道已全，則井冽而泉寒，為時所食。所謂「養而不窮，往來井井」，皆在此爻。象曰：中正也。</p><p>上六：井收，勿幕，有孚，元吉。象曰：「元吉」在上，大成也。五爻井冽可食；上爻水已在木上，綆汲而水出，功用及物矣。幕，所以蓋井也。井功貴出，無用幕也。澤既及物，故曰「有孚」；井道大成，故曰「元吉」。象曰：「元吉」在上，大成也。䷰ 離下兌上</p><p>革革：巳日乃孚，元亨，利貞，悔亡。彖曰：「革」，水火相息，二女同居，其志不相得，曰「革」。「巳日乃孚」，革而信之。文明以說，大亨以正，革而當，其悔乃亡。天地革而四時成，湯、武革命，順乎天而應乎人。革之時義大矣哉！</p><p>澤上火下，澤所以瀦水也，水涸而火居焉，非常之變也，其卦為「革」。唐、虞禪，夏後、殷、周繼聖人以天下世其子，然不能必後世子孫之皆賢也。有聖人起而易置之，是其心也。聖人不忍天下之塗炭，乃身負犯上之名，以合天人之心，此天地之大變也，而其事見於革。文王三分天下有其二，以服事商，其事見於明夷。文王非不能革也，時未當革，聖人不敢先；時而當革，聖人不敢後。聖人不能違時，能不失時而已。文王晦其事於爻，夫子發其秘於彖。學者即彖以觀爻，則「革」之義著矣。曰革，巳日乃孚。時既當革，則信於心而革之，雖聖人不敢私也。「利貞」，革以正也。有湯武之志則可，無湯武之志則亂也。悔亡。聖人舉事，必得萬全，事已而孚，安得有悔？彖義甚明。</p><p>象曰：澤中有火，革。君子以治歷明時。</p><p>「澤而有火」，澤之變也。治歷明時，所以察時之變。</p><p>初九：鞏用黃牛之革。象曰：「鞏用黃牛」，不可以有為也。居「革」之下，未嘗革也，則固守臣節而不敢以妄動。牛革堅牣之至言，而此自固也。時未可革，湯武未嘗一日有無君之心也。象曰：不可以有為也。</p><p>六二：巳日乃革之，徵吉，無咎。象曰：「巳日革之」，行有嘉也。以臣革君，自此而往。「巳日」，時已至也。時既當革，則往而得吉，且「無咎」也。湯以七十里，文王以百里，天應人順，湯武不敢辭徂徵而壺漿，迎仗鉞而元黃。至是惟無往，往則無敵於天下矣。象曰「行有嘉也」。</p><p>九三：徵㓙貞厲，革言三就，有孚。象曰：「革言三就」，又何之矣。</p><p>三處疑地，聖人以身任天下之變，雖欲無革，不容無革。曰「徵㓙貞厲」，進退皆危機也。故言必三複既信而後行之。升陑之師，必在伊尹「五就」之後，而孟津之後，亦遲於三年。觀兵之餘，皆「革言三就」之餘也。象曰「又何之矣」，三就之後，何往不可。</p><p>九四：悔亡，有孚，改命吉。象曰：「改命」之吉，信志也。</p><p>四處下卦之上，「乾」道乃革之位也。變夏為商，變商為周，時之既至，聖人不能卻其來。悔既亡，眾既孚，則改命而吉矣。象曰「信志也」。湯武之革。湯武之心固自信，天下之心亦無不信，蓋非利也，為匹夫匹婦復仇也。九五：大人虎變，未佔有孚。象曰：「大人虎變」，其文炳也。五正君位，聖人既作，萬物鹹睹，天下皆利見也。然攸徂之民，室家胥慶於未來蘇之前；孟津之師，八百國不期而自至。天下之孚，不在於既佔之後也。故曰：「大人虎變，未佔有孚。」象曰：其文炳也。</p><p>上六：君子豹變，小人革面，徵㓙居貞吉。象曰：「君子豹變」，其文蔚也；「小人革面」，順以從君也。</p><p>至此，天下鹹革矣。君子自奮，以副拔擢，小人洗濯以聽新政。然征伐非聖人之得已也，事已則歸馬放牛，載橐弓矢，示不復用。蓋既革之後，不可復徵也。故於既革之終，戒以徵㓙居貞吉。象曰：「君子豹變」，其文蔚也；「小人革面」，順以從君也。䷱ 巽下離上</p><p>鼎</p><p>鼎：元吉，亨。彖曰：鼎，象也。以木巽火，亨飪也。聖人亨以享上帝，而大亨以養聖賢。巽而耳目聰明，柔進而上行，得中而應乎剛，是以元亨。鼎，鼎象也。全卦有鼎象，初為鼎足，二三四為鼎實，五為鼎耳，上為鼎鉉。巽木離火，以木巽火，又鼎之用也，故名卦以鼎。大抵聖人制器，皆有個自然之象。昔禹平水土，九牧貢金，於是象物以鑄鼎，示人知所避，歷代傳之，以為寶器。武王克商，遷九鼎於洛邑。武王宅洛，定鼎郟鄏，卜世三十，卜年八百。及周之衰，楚子問鼎，周人假設以對，以為在德不在鼎。秦漢而下，鼎已淪亡。武帝得寶鼎於汾陰，薦告宗廟，作為詩歌，見於史冊。然則鼎者，國家之重器也。聖人重易，巽下離上，已有其象，故曰「鼎」。鼎，重器也。主器必長子，故曰「元」。得鼎則昌，失鼎則亡，故曰「吉」。用以享上帝，養聖賢，可以通於神明矣，故曰「亨」。彖曰：「鼎」，象也，言卦有其象也。以木巽火，亨飪之義也。亨以享上帝，大亨以養聖賢，皆鼎之用也。下體巽，上體離，離為目，為文明，五為鼎耳，故曰「巽而耳目聰明」。六五一柔進居君位，下應九二之剛，此蓋鼎實在二，鼎耳在五，二五相應，鼎道已全，故曰：「得中而應乎剛，是以元亨。」</p><p>象曰：木上有火，「鼎」；君子以正位凝命。</p><p>「正位凝命」，主器者之事也。「離」麗乎上，所以「正位」；「巽」申乎下，所以「凝命」。</p><p>初六，鼎顛趾，利出否。得妾以其子，無咎。象曰：「鼎顛趾」，未悖也；「利出否」，以從貴也。</p><p>以全卦之象言之，初為「趾」，二三四為「實」，五為「耳」，上為「鉉」，全體一「鼎」象也。分上下體之象而觀之，則上下體為二「鼎」。上體之鼎有耳而無足，故九四雲：「鼎折足」；下體之鼎有足而無耳，故九三雲：「鼎耳革。」六爻皆是取取象，故彖總言之曰「鼎象」也。初為鼎足。「趾」，足也。鼎有三足，今二而已。蓋「顛」，傾也，傾則見其二而已，顛趾則傾鼎以出穢。「否」，穢也，出穢以納新也，取新之義也。凡人納妾，多出於夷俘賤隸，但以其子之可貴，豈計其所出之卑汙也？亦棄穢取新之義也。子以主器，故於「鼎」之初言之，如是則雖「顛趾」而「無咎」矣。象曰「未悖也」，言趾非直顛也，以出穢而顛，是故鼎道未悖。「利出否」，以從貴也，妾以子貴故也。</p><p>九二，鼎有實，我仇有疾，不我能即，吉。象曰：「鼎有實」，慎所之也；「我仇有疾」，終無尤也。</p><p>二為鼎實，以剛居中，「有實」之象也。五，二之匹也。五為鼎耳，麗乎上體，不能下接，有相疾之象。然耳麗鼎上，若圯而下，則鼎虧矣。雖不我即，然終吉也。象曰：慎所之也。耳麗乎上，二為鼎實，不能上往，故曰「慎所之」。賴乎二不上往，五不下接，而鼎道全，故「終無尤」。</p><p>九三，鼎耳革，其行塞，雉膏不食，方雨虧悔，終吉。象曰：「鼎耳革」，失其義也。</p><p>三在下體之上，分上下體言之，有足而無耳，耳革則不能舉以行，而「其行塞」。離為上，為雉，鼎既無耳，雉無所立，故不下食。觀高宗彤日，雉升鼎耳而嗚，今鼎耳既革，宜其不食也。若與上體合，陰陽相合，而鼎體全而悔散矣，故曰「方雨虧悔，終吉」。象曰「失其義也」，言耳革則失鼎之義也。</p><p>九四，鼎折足，覆公餗，其形渥㓙。象曰：「覆公餗」，信如何也！四居上體之下，分上下體而言之。有耳而無足，足既折，其餗必覆，不勝鼎之任也，故慚靦見乎色，而其形渥然，象曰「信如何也」。繫辭曰：「德薄而位尊，知小而謀大，力小而任重，鮮不及矣。」易曰：「鼎折足，覆公餗，其形渥，兇。」言不勝其任也。</p><p>六五，鼎黃耳金鉉，利貞。象曰：「鼎黃耳」，中以為實也。五，鼎耳也。鼎之舉動在耳，五為鼎主，位得中。黃，中色也，故曰「黃耳」。鉉所以舉鼎而行，九居上，金鉉也。五必得上，鼎體乃全，未與上合，利在乎貞，蓋未可行也。象曰「中以為實也。」以黃取中義。</p><p>上九，鼎玉鉉，大吉，無不利。象曰：玉鉉在上，剛柔節也。上，鼎之鉉。玉，和物也。鼎道貴和，得玉鉉則陰陽和也，而鼎之功成矣。鉉，一也，五取金鉉，上取玉鉉。金以剛為義，玉以和為義。五體柔，故以剛為貴；上體剛，故以和為貴。離上為火，而鉉居之，金畏火而玉不畏火，故成鼎之功以玉為貴也。鼎之功成，則享帝養賢，而鼎道亨矣，故「大吉，無不利」。象曰：「剛柔節也」，言陰陽和而得剛柔之節也。西溪易說卷十，</p>',73)])])}const x=a(i,[["render",r]]);export{m as __pageData,x as default};
